-- O cache de preço de material do orçamentista — multi-supplier, com LINK.
--
-- v4 de 17/08/2026: a mesma variante agora existe em até 5 fornecedores
-- (Screwfix, B&Q, Travis Perkins, Wickes, Toolstation — Selco bloqueia bot),
-- cada linha com o PRODUTO exato e a URL de onde o preço saiu, porque preço
-- sem link não se confere ("ja deixar link de onde voce quoted", dono, 17/08).
-- Selecionado por curadoria, não por listing: tamanho tem que bater, pack é
-- dividido com a conta gravada no spec (pack_math), par é par, e produto
-- errado fica FORA com motivo (aço não é madeira, semente não é grama,
-- suporte comum não é heavy duty). Balcão trade mostra preço ex-VAT: o
-- unit_cost aqui é SEMPRE inc VAT, com o ex_vat no spec quando veio.
--
-- A REGRA DE PREÇO (dono, 17/08, segunda iteração): vender competindo com o
-- mercado e comprar do mais barato. O preço de venda de uma variante é a
-- MÉDIA entre os fornecedores (nunca abaixo de custo × 1.30, o piso de 30%
-- continua), o custo é o MENOR preço, e a margem — agora exposta em % — é a
-- consequência: média de ~140% contra os 30% fixos de antes. A conta vive na
-- view material_quotes, então os fatos ficam fatos e a política fica num
-- lugar só. O list_price por linha (custo × 1.30) permanece como referência
-- do piso por fornecedor, não como preço de venda.
--
-- Nenhum fornecedor domina (vitórias por menor preço: Screwfix 24, B&Q 15,
-- Wickes 14, Toolstation 10, TP 6) — é exatamente por isso que o orçamentista
-- compara em vez de casar com um. `unit_cost` é FATO; `list_price` é POLÍTICA
-- (markup 1.30, regra do dono: material sempre com 30%). O supplier-RPA
-- renova por TTL (~30d) — os packs da cerca já mudaram de preço entre ontem
-- e hoje, então isso não é luxo. 5 linhas Screwfix são resgate do cache de
-- 17/08 (busca fresca não reachou o produto; spec.nota marca, link de busca).
--
-- Atenção de variante herdada para a próxima rodada: "porta interna" mistura
-- slab liso de £35-46 (TP/B&Q) com Shaker de £128+ (Screwfix/Toolstation) —
-- o gap é de ESTILO, não de fornecedor; family internal_door pede variantes
-- de estilo (flush vs shaker vs panel) antes de cotar às cegas pelo mínimo.
-- Fonte da demanda: docs/demanda-varredura-2026-08-17.json.

create table if not exists supplier_prices (
  id             uuid primary key default gen_random_uuid(),
  family         text not null,
  variant        text not null,
  query          text not null,
  supplier       text not null default 'screwfix',
  unit_cost      numeric(10,2) not null,
  markup         numeric(4,2) not null default 1.30,
  list_price     numeric(10,2) not null,
  spec           jsonb not null default '{}'::jsonb,
  sample_product text,
  source_url     text,
  fetched_at     timestamptz not null default now(),
  created_at     timestamptz not null default now(),
  unique (supplier, family, variant),
  unique (supplier, query)
);

comment on table supplier_prices is
  'Cache de preço de material multi-supplier com link (orçamentista). unit_cost = fato inc VAT; list_price = unit_cost x 1.30 (política). spec traz pack_math/ex_vat; produto errado não entra.';

create index if not exists supplier_prices_family_idx on supplier_prices (family);
create index if not exists supplier_prices_query_idx on supplier_prices (query);

on conflict (supplier, query) do nothing;

-- A política de preço em um lugar só: o orçamentista cota DAQUI.
-- custo = menor preço entre fornecedores (é de quem compramos, com link);
-- nosso_preco = média do mercado, nunca abaixo de custo × 1.30, terminado em .99;
-- margem_pct = sobre o custo, porque é assim que o negócio fala de margem.
create or replace view material_quotes as
with agg as (
  select family, variant,
         min(unit_cost) as custo,
         avg(unit_cost) as media,
         max(unit_cost) as mais_caro,
         count(*)       as fontes
  from supplier_prices
  group by family, variant
),
melhor as (
  select distinct on (family, variant)
         family, variant, supplier as compra_de, sample_product, source_url
  from supplier_prices
  order by family, variant, unit_cost asc
)
select a.family, a.variant, m.compra_de, a.custo,
       round(a.media, 2)     as media,
       a.mais_caro,
       (floor(greatest(a.media, a.custo * 1.30)) + 0.99)::numeric(10,2) as nosso_preco,
       round(((floor(greatest(a.media, a.custo * 1.30)) + 0.99) - a.custo) / a.custo * 100) as margem_pct,
       a.fontes, m.sample_product, m.source_url
from agg a
join melhor m using (family, variant);
